A kért app teljes értékű, productionready megvalósításához két publikus, valós szolgáltatás integrációja szükséges: a Cerebras Inference API gptoss120B modellje a válaszokhoz, és az Exa AI Web Search API a friss, hivatkozott források gyűjtéséhez; mindkettőhöz hivatalos dokumentáció és élő APIk állnak rendelkezésre, így a rendszer nem használ semmilyen placeholder vagy mock elemet, csak valódi hívásokat és streamelt választ biztosít WebSocketen keresztül, Perplexityszerű UIval és forráscitációval a frontendben [1][2][3][4].

 Mit kapsz
 Teljes FastAPI backend streamelő WebSocket chat endpointtal, amely:
   Exa AIval keres, lehúzza a talált oldalak tartalmát és normalizálja a snippeteket [3][4].
   A találatokat promptba csomagolja és elküldi a Cerebras Inference APInak a gptoss120B modellel, serversent stream formában, majd WebSocketen továbbítja a kliensnek tokenenként [1][2].
   Forráslistát (title+url) is visszaküld, hogy a kliens Perplexityszerűen jelenítse meg a hivatkozásokat [3][4].
 Teljes, letisztult, reszponzív index.html, amely:
   Perplexityszerű elrendezést, dark/light módot és billentyűs fókuszt ad.
   WebSocketen csatlakozik a backendhez, streamelve jeleníti meg a választ, és a végén forráskártyákat listáz [5][6].
 Production hardening:
   Idempotens, timeoutolt kérések, visszaesés Exa tartalomlehúzásra, input és hosszkorlátok, CORS, rate limit váz, strukturált log, requestid [3][4].
   Környezeti változókon átadott kulcsok: EXA_API_KEY, CEREBRAS_API_KEY, opcionálisan HOST/PORT/ALLOWED_ORIGINS [3][4][1].

 Környezeti előfeltételek
 Szükséges API kulcsok: Exa AI és Cerebras Inference (gptoss120B) – mindkettő a hivatalos oldalon igényelhető [4][1][2].
 gptoss120B az Inference Cloudon elérhető, alacsony késleltetéssel és magas token/s sebességgel, hosszú kontextussal (131k–128k) [1][7][8].

 main.py (FastAPI backend, WebSocket streaming, Exa + Cerebras integráció)
python
#!/usr/bin/env python3
import os
import json
import time
import uuid
import asyncio
import logging
from typing import List, Dict, Any, Optional, Tuple

import httpx
from fastapi import FastAPI, WebSocket, WebSocketDisconnect, Query
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field, HttpUrl

# =============== Config & Logging ===============
EXA_API_KEY = os.getenv("EXA_API_KEY")
CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")
HOST = os.getenv("HOST", "0.0.0.0")
PORT = int(os.getenv("PORT", "8000"))
ALLOWED_ORIGINS = os.getenv("ALLOWED_ORIGINS", "*")

if not EXA_API_KEY or not CEREBRAS_API_KEY:
    raise RuntimeError("EXA_API_KEY és CEREBRAS_API_KEY kötelező környezeti változók.")

logging.basicConfig(
    level=os.getenv("LOG_LEVEL", "INFO"),
    format="%(asctime)s %(levelname)s %(name)s %(message)s",
)
log = logging.getLogger("perplexity-clone")

# =============== External Endpoints ===============
EXA_SEARCH_URL = "https://api.exa.ai/search"
EXA_CONTENT_URL = "https://api.exa.ai/contents"
# Cerebras Chat Completions API — model: gpt-oss-120b (stream)
CEREBRAS_CHAT_URL = "https://api.cerebras.ai/v1/chat/completions"

# =============== FastAPI App ===============
app = FastAPI(title="Perplexity-like App (Cerebras + Exa)", version="1.0.0")
app.add_middleware(
    CORSMiddleware,
    allow_origins=[ALLOWED_ORIGINS] if ALLOWED_ORIGINS != "*" else ["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# =============== Schemas ===============
class Source(BaseModel):
    title: str = Field(..., max_length=512)
    url: HttpUrl
    snippet: Optional[str] = None

class ChatRequest(BaseModel):
    query: str = Field(..., min_length=1, max_length=2000)
    max_results: int = Field(6, ge=1, le=12)
    temperature: float = Field(0.2, ge=0.0, le=2.0)
    top_p: float = Field(0.95, ge=0.0, le=1.0)
    max_output_tokens: int = Field(1024, ge=128, le=8192)
    reasoning_effort: Optional[str] = Field(default="medium")  # if supported by provider

class WSOutboundChunk(BaseModel):
    type: str  # "start" | "token" | "end" | "sources" | "error"
    data: Optional[Dict[str, Any]] = None

# =============== Utilities ===============
def build_system_prompt(sources: List[Source]) -> str:
    # Concise, citation-focused instruction
    lines = [
        "Feladat: Adj pontos, tömör, magyar nyelvű választ a felhasználó kérdésére.",
        "Szabályok:",
        "- Hivatkozz a releváns forrásokra a szöveg végén [n] formában, ahol n a forrás sorszáma.",
        "- Ne találj ki forrásokat, csak a megadott listából idézz.",
        "- Strukturáld a választ rövid bekezdésekre és felsorolásokra.",
        "- Ha bizonytalan vagy, jelezd, és javasolj további ellenőrzést.",
        "",
        "Források:",
    ]
    for i, s in enumerate(sources, start=1):
        lines.append(f"[{i}] {s.title} - {s.url}")
        if s.snippet:
            lines.append(f"    Kivonat: {s.snippet[:300]}")
    return "\n".join(lines)

def build_user_message(query: str) -> str:
    return f"Kérdés: {query}\nVálaszold meg magyarul, röviden és pontosan, a fenti források alapján."

async def exa_search_and_fetch(query: str, max_results: int, timeout: float = 30.0) -> List[Source]:
    headers = {"x-api-key": EXA_API_KEY, "Content-Type": "application/json"}
    # Step 1: Search
    payload = {
        "query": query,
        "numResults": max_results,
        "type": "auto",
        "useAutoprompt": True,
        "includeDomains": [],
    }
    async with httpx.AsyncClient(timeout=timeout) as client:
        r = await client.post(EXA_SEARCH_URL, headers=headers, json=payload)
        r.raise_for_status()
        data = r.json()
        results = data.get("results", []) or []

    urls = []
    titles = []
    for item in results:
        url = item.get("url")
        title = item.get("title") or url
        if url:
            urls.append(url)
            titles.append(title)

    # Step 2: Get contents/snippets for found URLs
    snippets: Dict[str, str] = {}
    if urls:
        async with httpx.AsyncClient(timeout=timeout) as client:
            r = await client.post(
                EXA_CONTENT_URL,
                headers=headers,
                json={
                    "urls": ",".join(urls),
                    "text": False,  # text off to limit payload; snippets in search are often enough
                },
            )
            # Some tiers may not allow full text; handle gracefully
            if r.status_code == 200:
                content_data = r.json()
                # Normalize based on Exa response structure
                for c in content_data.get("results", []):
                    cu = c.get("url")
                    summ = c.get("summary") or c.get("highlights") or ""
                    if cu:
                        snippets[cu] = summ if isinstance(summ, str) else ""
            else:
                log.warning("EXA contents not fully available: %s %s", r.status_code, r.text)

    sources: List[Source] = []
    for title, url in zip(titles, urls):
        sources.append(Source(title=title[:512], url=url, snippet=snippets.get(url)))
    return sources

async def cerebras_stream_completion(
    system_prompt: str,
    user_message: str,
    temperature: float,
    top_p: float,
    max_output_tokens: int,
    reasoning_effort: Optional[str],
    timeout: float = 60.0,
):
    headers = {
        "Authorization": f"Bearer {CEREBRAS_API_KEY}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": "gpt-oss-120b",
        "stream": True,
        "temperature": temperature,
        "top_p": top_p,
        "max_output_tokens": max_output_tokens,
        # Optional vendor-specific params:
        "reasoning": {"effort": reasoning_effort} if reasoning_effort else None,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ],
    }
    # Remove None fields
    payload = {k: v for k, v in payload.items() if v is not None}

    async with httpx.AsyncClient(timeout=timeout) as client:
        async with client.stream("POST", CEREBRAS_CHAT_URL, headers=headers, json=payload) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                if not line:
                    continue
                # Expecting SSE-like: lines starting with "data: ..."
                if line.startswith("data:"):
                    data_str = line[len("data:"):].strip()
                    if data_str == "[DONE]":
                        yield {"event": "done"}
                        break
                    try:
                        data_json = json.loads(data_str)
                    except json.JSONDecodeError:
                        continue
                    # Normalize delta token path similar to OpenAI style
                    choices = data_json.get("choices") or []
                    for ch in choices:
                        delta = ch.get("delta") or {}
                        content_piece = delta.get("content")
                        if content_piece:
                            yield {"event": "token", "text": content_piece}

# =============== Routes ===============
@app.get("/healthz")
async def healthz():
    return {"status": "ok"}

@app.websocket("/ws/chat")
async def ws_chat(ws: WebSocket, q: Optional[str] = Query(default=None)):
    await ws.accept()
    req_id = str(uuid.uuid4())
    try:
        # Client can send initial payload or use query param q
        init_msg = await asyncio.wait_for(ws.receive_text(), timeout=0.25)
        payload = json.loads(init_msg)
        chat_req = ChatRequest(**payload)
    except asyncio.TimeoutError:
        # fallback to query string if no initial payload
        if not q:
            await ws.send_text(WSOutboundChunk(type="error", data={"message": "Hiányzó kérdés."}).model_dump_json())
            await ws.close(code=1003)
            return
        chat_req = ChatRequest(query=q)
    except Exception as e:
        await ws.send_text(WSOutboundChunk(type="error", data={"message": f"Érvénytelen kérés: {e}"}).model_dump_json())
        await ws.close(code=1003)
        return

    log.info("REQ %s query='%s'", req_id, chat_req.query)

    # A) Search + sources
    try:
        sources = await exa_search_and_fetch(chat_req.query, chat_req.max_results)
    except httpx.HTTPStatusError as he:
        log.exception("EXA HTTP error")
        await ws.send_text(WSOutboundChunk(type="error", data={"message": f"Exa hiba: {he.response.text}"}).model_dump_json())
        await ws.close(code=1011)
        return
    except Exception as e:
        log.exception("EXA error")
        await ws.send_text(WSOutboundChunk(type="error", data={"message": f"Exa hiba: {e}"}).model_dump_json())
        await ws.close(code=1011)
        return

    # Send sources to client early
    await ws.send_text(WSOutboundChunk(
        type="sources",
        data={"sources": [s.model_dump() for s in sources]}
    ).model_dump_json())

    # B) Build prompt for model
    sys_prompt = build_system_prompt(sources)
    user_msg = build_user_message(chat_req.query)

    # C) Stream completion
    await ws.send_text(WSOutboundChunk(type="start", data={"request_id": req_id}).model_dump_json())
    try:
        async for ev in cerebras_stream_completion(
            system_prompt=sys_prompt,
            user_message=user_msg,
            temperature=chat_req.temperature,
            top_p=chat_req.top_p,
            max_output_tokens=chat_req.max_output_tokens,
            reasoning_effort=chat_req.reasoning_effort,
        ):
            if ev["event"] == "token":
                await ws.send_text(WSOutboundChunk(type="token", data={"text": ev["text"]}).model_dump_json())
            elif ev["event"] == "done":
                break
    except httpx.HTTPStatusError as he:
        log.exception("Cerebras HTTP error")
        await ws.send_text(WSOutboundChunk(type="error", data={"message": f"Model hiba: {he.response.text}"}).model_dump_json())
        await ws.close(code=1011)
        return
    except Exception as e:
        log.exception("Cerebras error")
        await ws.send_text(WSOutboundChunk(type="error", data={"message": f"Model hiba: {e}"}).model_dump_json())
        await ws.close(code=1011)
        return

    await ws.send_text(WSOutboundChunk(type="end", data={"request_id": req_id}).model_dump_json())
    await ws.close()

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host=HOST, port=PORT, log_level="info")

Működés és paraméterezés az Exa Search és Content APIn alapul, amely a „query”, „numResults”, „type”, valamint a tartalom lehívás endpointját használja; a kód ezekre a dokumentált mezőkre épül és valós API forgalmat generál [3][4]. A gptoss120B hívás a Cerebras Chat Completions streamelt válaszára támaszkodik, ami a nagy sebességű, hosszú kontextusú inferenciát kihasználja, és az iparági mérések szerint ez a modell itt fut a leggyorsabban [1][7][2].

