            <div style="font-weight:700;margin-bottom:6px;">Források</div>
            <div id="sourcesList" style="display:flex;flex-direction:column;gap:8px;"></div>
          </div>
        </aside>
      </div>

      <div class="composer">
        <textarea id="input" placeholder="Kérdezz bármit (Perplexity-stílusú keresés)..."></textarea>
        <button id="send">Küldés</button>
      </div>

      <div class="footer">
        Streamelt válaszok gpt-oss-120B (Cerebras) és Exa AI integrációval. Üzemkész végpont: /ws/chat. 
      </div>
    </div>

    <script>
      const messagesEl = document.getElementById('messages');
      const sourcesListEl = document.getElementById('sourcesList');
      const inputEl = document.getElementById('input');
      const sendBtn = document.getElementById('send');
      const statusEl = document.getElementById('status');

      let ws = null;
      let assistantBuffer = '';
      let assistantMsgEl = null;

      function appendMessage(text, role) {
        const div = document.createElement('div');
        div.className = 'msg ' + role;
        div.textContent = text;
        messagesEl.appendChild(div);
        messagesEl.scrollTop = messagesEl.scrollHeight;
        return div;
      }

      function renderSources(sources) {
        sourcesListEl.innerHTML = '';
        sources.forEach((s, idx) => {
          const card = document.createElement('div');
          card.className = 'src-card';
          card.innerHTML = `
            <div style="font-weight:600;margin-bottom:4px;">[${idx+1}] ${escapeHtml(s.title)}</div>
            <a href="${s.url}" target="_blank" rel="noopener">${s.url}</a>
          `;
          sourcesListEl.appendChild(card);
        });
      }

      function escapeHtml(str) {
        return (str ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
      }

      function connectAndAsk(query) {
        if (!query.trim()) return;
        sendBtn.disabled = true;
        statusEl.textContent = 'Csatlakozás...';

        ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '/ws/chat');

        const userMsg = appendMessage(query, 'user');
        assistantBuffer = '';
        assistantMsgEl = appendMessage('', 'assistant');

        ws.onopen = () => {
          statusEl.textContent = 'Keresés és összegzés folyamatban...';
          ws.send(JSON.stringify({
            query,
            max_results: 6,
            temperature: 0.2,
            top_p: 0.95,
            max_output_tokens: 1024,
            reasoning_effort: 'medium'
          }));
        };

        ws.onmessage = (event) => {
          try {
            const msg = JSON.parse(event.data);
            if (msg.type === 'sources') {
              renderSources(msg.data.sources || []);
            } else if (msg.type === 'start') {
              statusEl.textContent = 'Válasz streamelve...';
            } else if (msg.type === 'token') {
              assistantBuffer += msg.data.text;
              assistantMsgEl.textContent = assistantBuffer;
              messagesEl.scrollTop = messagesEl.scrollHeight;
            } else if (msg.type === 'end') {
              statusEl.textContent = 'Készen áll';
              sendBtn.disabled = false;
              ws.close();
            } else if (msg.type === 'error') {
              statusEl.textContent = 'Hiba: ' + (msg.data && msg.data.message ? msg.data.message : 'ismeretlen');
              sendBtn.disabled = false;
              ws.close();
            }
          } catch (e) {
            console.error('Bad message', e);
          }
        };

        ws.onerror = (e) => {
          statusEl.textContent = 'Hálózati hiba';
          sendBtn.disabled = false;
        };

        ws.onclose = () => {
          sendBtn.disabled = false;
        };
      }

      sendBtn.addEventListener('click', () => {
        connectAndAsk(inputEl.value);
      });

      inputEl.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          connectAndAsk(inputEl.value);
        }
      });
    </script>
